$string['panel_bychannel_adlater_all'] = 'Dejaron después su contacto en un anuncio, aunque llegaron por otro canal: {$a}.';
$string['panel_bychannel_best'] = 'Entre los canales con al menos {$a->fair} familias, el que más matricula es {$a->best} ({$a->bestfrac}) y el que menos, {$a->worst} ({$a->worstfrac}).';
$string['panel_bychannel_foot'] = 'Cómo se cuenta: el origen es el primer contacto medido y no cambia después. Una jornada, una llamada o el cartel de la puerta son puertas, nunca el origen, y un anuncio solo cuenta si la familia era nueva. La ficha de Google, por utm_medium=ficha; la publicidad, por un medio de pago (cpc, paid, ads, campaign); los correos y mensajes del centro, por email, newsletter o sms; los impresos, por qr o impreso; las redes, por social o por venir de una red; la web del centro, por el dominio de su correo o por sus formularios. Sin nada medido, cuenta lo que dijo la familia en «¿Cómo nos conocieron?»; si tampoco lo dijo, va a «Sin medir» y no se atribuye a nadie. Ningún canal se lleva más de lo medido: un anuncio visto sin pulsar no deja rastro y puede acabar en una búsqueda o en una visita directa a la web, y quien deja su contacto en un anuncio pudo conocer el centro antes. Quiénes son sale de las listas del centro, de lo que dicen las familias y el equipo, y de la lista de antiguos alumnos.';
