$string['panel_isthis_bridge'] = 'Un puente trae a Eguahe lo que llega por otra herramienta (los anuncios de Google o Meta, el buzón de admisiones o un formulario que el centro ya usa), para que cada familia esté en su ficha y se le conteste desde la bandeja.';
$string['panel_isthis_entries'] = 'Una entrada es un sitio por donde llegan las familias: el formulario de la web del centro, un QR en un cartel, el buzón de admisiones o los anuncios de Google o Meta. Cada familia que llega por una de ellas cuenta como una llegada, y aquí se ve cuál trae más.';
$string['panel_isthis_forecast'] = 'La previsión calcula, con los niños de la zona y lo que pasó en otras campañas, cuántas familias podrían pedir plaza en cada curso. No es una promesa: es un margen razonable para preparar plazas y grupos.';
$string['panel_isthis_kit'] = 'El kit es lo que se comparte para que las familias se inscriban en un acto: el enlace, el QR para el cartel, los carteles y los textos para las redes y el canal, listos para copiar.';
$string['panel_isthis_labels'] = 'Las etiquetas de mochila llevan el nombre de cada niño escrito a mano, como en su página. Se imprimen en hojas de pegatinas y se les dan en la puerta del acto.';
$string['panel_isthis_metrics'] = 'Cifras cuenta cómo va la campaña: cuántas familias preguntan, cuántas vienen y cuántas se matriculan, por dónde llegan y cuántas plazas quedan. Cada número lleva debajo lo que cuenta.';
$string['panel_isthis_renewal'] = 'Aquí se pregunta a las familias que ya están en el centro si sus hijos siguen el curso que viene. Contestan en su página con un toque, y se ve, curso a curso, quién sigue, quién no y quién aún no lo sabe: así se sabe cuántas plazas quedan para alumnos nuevos.';
$string['panel_isthis_start'] = 'El primer día es el día que empieza cada curso. Aquí se marca a cada niño que empieza, y con esa fecha Eguahe sabe cuándo darle a su familia el cuento de su primer día y cuándo preguntarles cómo fue.';
