$string['panel_voice_channel'] = 'Por canal';
$string['panel_voice_channel_def'] = 'De dónde vienen de verdad: el primer contacto medido de cada familia, nunca la jornada o el formulario por donde entró, y con las que se perdieron también. Primero, los canales del propio centro (su web, los buscadores, los asistentes de IA, su ficha de Google, sus redes, sus correos y mensajes, y el boca a boca); después, la publicidad; después, otros caminos (impresos y QR, otras webs, sin pasar por la web), y al final lo que no se midió. Cada canal, con hasta dónde llegaron sus familias y quiénes son: las nuevas de verdad, las que ya eran del centro (que no cuentan en el resto de las cifras), las que ya tuvieron hijos en él y las de antiguos alumnos.';
